using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Threading;using System.Windows.Interop;
namespace DesktopBox {
public static class DesktopFileProperties {
 [System.Runtime.InteropServices.DllImport("shell32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode)]static extern bool SHObjectProperties(IntPtr owner,uint flags,string path,string page);
 public static void Show(Window owner,string path){if(!SHObjectProperties(new WindowInteropHelper(owner).Handle,2,path,null))throw new IOException("无法打开文件属性");}
}
// Both views refer to physical files. Groups and sorting stay in their own models.
public sealed class DesktopFiles:IDisposable {
 readonly Store main,shelf;readonly Action render;readonly Dispatcher dispatcher;readonly DispatcherTimer pending;readonly Dictionary<string,FileSystemWatcher> watchers=new Dictionary<string,FileSystemWatcher>(StringComparer.OrdinalIgnoreCase);bool busy,disposed,contentChanged;int mutations;public readonly string Root;public string Error="";public event Action<string,string,bool> PathChanged;
 public DesktopFiles(Store primary,Store files,string root,Action redraw){main=primary;shelf=files;Root=Path.GetFullPath(root).TrimEnd('\\');if(!Directory.Exists(Root))throw new DirectoryNotFoundException(Root);render=redraw;dispatcher=Dispatcher.CurrentDispatcher;pending=new DispatcherTimer(DispatcherPriority.Background){Interval=TimeSpan.FromMilliseconds(180)};pending.Tick+=(o,e)=>{pending.Stop();TrySync();};main.Changed+=Request;shelf.Changed+=Request;}
 public static bool Ordinary(string path){if(String.IsNullOrWhiteSpace(path)||EntryPath.IsShell(path))return false;string ext=Path.GetExtension(path);return !new[]{".lnk",".url",".appref-ms",".exe",".com"}.Contains(ext,StringComparer.OrdinalIgnoreCase);}
 public bool Physical(string path){return !EntryPath.IsShell(path)&&DesktopStorage.Under(path,Root)&&!String.Equals(path.TrimEnd('\\'),Root,StringComparison.OrdinalIgnoreCase);}
 public bool Managed(string path){return Ordinary(path)&&Physical(path);}
 public bool HasStore(Store store){return Object.ReferenceEquals(store,main)||Object.ReferenceEquals(store,shelf);}
 public void Request(){if(disposed||busy)return;if(!dispatcher.CheckAccess()){dispatcher.BeginInvoke(new Action(Request));return;}pending.Stop();pending.Start();}
 void TrySync(){try{Sync();Error="";}catch(Exception ex){Error=ex.Message;}Record();}
 static bool Same(string a,string b){return String.Equals(a,b,StringComparison.OrdinalIgnoreCase);}
 public static void Rewrite(Model model,string oldPath,string newPath,bool folder){foreach(var item in model.Items){if(EntryPath.IsShell(item.Path))continue;if(Same(item.Path,oldPath)||(folder&&item.Path.StartsWith(oldPath.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))){string path=newPath+item.Path.Substring(oldPath.Length);item.Path=path;item.Name=EntryPath.Title(path);item.SourcePath="";}}}
 public void Renamed(string oldPath,string newPath,bool folder){if(disposed)return;busy=true;try{foreach(var store in new[]{main,shelf})Rewrite(store.Data,oldPath,newPath,folder);if(PathChanged!=null)PathChanged(oldPath,newPath,folder);main.Save();shelf.Save();}finally{busy=false;}Sync();if(render!=null)render();}
 public void Removed(string path,bool folder){busy=true;try{foreach(var store in new[]{main,shelf}){RecycleEntry.RemoveEntries(store.Data,path,folder);store.Save();}if(PathChanged!=null)PathChanged(path,null,folder);}finally{busy=false;}Sync();if(render!=null)render();}
 public void Sync(){if(disposed||busy||mutations>0)return;busy=true;bool changed=false;try{var disk=Directory.GetFileSystemEntries(Root).Where(path=>(File.GetAttributes(path)&(FileAttributes.Hidden|FileAttributes.System))==0).ToList();foreach(var store in new[]{main,shelf}){bool modified=false;foreach(var item in store.Data.Items.ToArray()){if(Physical(item.Path)&&!EntryPath.Exists(item.Path)){RecycleEntry.RemoveEntries(store.Data,item.Path,true);if(PathChanged!=null)PathChanged(item.Path,null,true);modified=true;}}
  var paths=disk.Concat(main.Data.Items.Where(i=>Physical(i.Path)&&EntryPath.Exists(i.Path)).Select(i=>i.Path)).Concat(shelf.Data.Items.Where(i=>Managed(i.Path)&&EntryPath.Exists(i.Path)).Select(i=>i.Path)).Where(path=>!Object.ReferenceEquals(store,shelf)||Ordinary(path)).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();
  foreach(string path in paths)if(!store.Data.Items.Any(i=>Same(i.Path,path))){store.Data.Items.Add(new Item{Path=path,Name=EntryPath.Title(path),Group="inbox"});modified=true;}
  if(Object.ReferenceEquals(store,shelf)){// This window is a desktop file view, not an app launcher.
   foreach(var item in store.Data.Items.ToArray())if(!Ordinary(item.Path)){store.Data.Items.Remove(item);modified=true;}
   foreach(var item in store.Data.Items.Where(i=>Managed(i.Path))){string name=EntryPath.Title(item.Path);if(item.Name!=name){item.Name=name;modified=true;}}
  }
  if(modified){store.Save();changed=true;}
 }UpdateWatchers();}finally{busy=false;Record();}if((changed||contentChanged)&&render!=null){contentChanged=false;render();}}
 void UpdateWatchers(){var parents=new HashSet<string>(new[]{Root},StringComparer.OrdinalIgnoreCase);foreach(var item in main.Data.Items.Concat(shelf.Data.Items).Where(i=>Physical(i.Path)))parents.Add(Path.GetDirectoryName(item.Path));foreach(string path in watchers.Keys.Where(p=>!parents.Contains(p)||!Directory.Exists(p)).ToArray()){watchers[path].Dispose();watchers.Remove(path);}foreach(string path in parents.Where(p=>Directory.Exists(p)&&!watchers.ContainsKey(p))){var watcher=new FileSystemWatcher(path){IncludeSubdirectories=false,NotifyFilter=NotifyFilters.FileName|NotifyFilters.DirectoryName|NotifyFilters.LastWrite};watcher.Created+=(o,e)=>Request();watcher.Deleted+=(o,e)=>Request();watcher.Changed+=(o,e)=>dispatcher.BeginInvoke(new Action(()=>{contentChanged=true;Request();}));watcher.Renamed+=(o,e)=>dispatcher.BeginInvoke(new Action(()=>{if(disposed)return;try{if(Physical(e.OldFullPath)&&Physical(e.FullPath))Renamed(e.OldFullPath,e.FullPath,Directory.Exists(e.FullPath));else Request();}catch(Exception ex){Error=ex.Message;Request();}}));watcher.Error+=(o,e)=>Request();watchers[path]=watcher;watcher.EnableRaisingEvents=true;}}
 public string Rename(string path,string name){if(!Physical(path)||!EntryPath.Exists(path))throw new InvalidOperationException("只能重命名桌面中的实际文件或文件夹");name=(name??"").Trim();if(name.Length==0||name=="."||name==".."||name.EndsWith(".")||name.EndsWith(" ")||name.IndexOfAny(Path.GetInvalidFileNameChars())>=0||new[]{"CON","PRN","AUX","NUL","COM1","COM2","COM3","COM4","COM5","COM6","COM7","COM8","COM9","LPT1","LPT2","LPT3","LPT4","LPT5","LPT6","LPT7","LPT8","LPT9"}.Contains(Path.GetFileNameWithoutExtension(name),StringComparer.OrdinalIgnoreCase))throw new InvalidDataException("文件名为空、包含非法字符或为 Windows 保留名称");string target=Path.Combine(Path.GetDirectoryName(path),name);if(Same(path,target)){if(path==target)return path;throw new InvalidDataException("仅更改字母大小写请在资源管理器中操作");}if(File.Exists(target)||Directory.Exists(target))throw new IOException("同名文件已存在，未覆盖");bool folder=Directory.Exists(path);if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("链接或联接请在资源管理器中处理");if(folder)Directory.Move(path,target);else File.Move(path,target);Renamed(path,target,folder);return target;}
 public void PromptRename(Window owner,Item item){TextBox input;var dialog=FrostSkin.Prompt(owner,"重命名文件","修改桌面实际文件名（包含扩展名）；主面板与文件窗口会同步。",EntryPath.Title(item.Path),out input);dialog.Loaded+=(o,e)=>{input.Focus();input.Select(0,Directory.Exists(item.Path)?input.Text.Length:Path.GetFileNameWithoutExtension(input.Text).Length);};if(dialog.ShowDialog()==true)Rename(item.Path,input.Text);}
 public void Copy(Item item,bool cut){if(!Physical(item.Path)||!EntryPath.Exists(item.Path))throw new IOException("文件不存在");var data=new DataObject();data.SetData(DataFormats.FileDrop,new[]{item.Path});data.SetData("Preferred DropEffect",new MemoryStream(BitConverter.GetBytes((int)(cut?DragDropEffects.Move:DragDropEffects.Copy))));Clipboard.SetDataObject(data,true);}
 public void Paste(){var data=Clipboard.GetDataObject();if(data==null||!data.GetDataPresent(DataFormats.FileDrop))return;var paths=(string[])data.GetData(DataFormats.FileDrop);bool cut=false;var effect=data.GetData("Preferred DropEffect") as MemoryStream;if(effect!=null&&effect.Length>=4)cut=(BitConverter.ToInt32(effect.ToArray(),0)&2)!=0;foreach(string source in paths){if(cut&&Same(Path.GetDirectoryName(source),Root))continue;DesktopStorage.Import(source,Root,null,cut,!cut);}Sync();}
 public void Record(){try{DeferredDiagnostics.Write(Path.Combine(main.Root,"desktop-files-state.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{Root,Error,watchers=watchers.Count,main=main.Data.Items.Count,files=shelf.Data.Items.Count,mode="shared physical desktop files; external ordinary file imports move to desktop"}));}catch{}}
 public void BeginMutation(){mutations++;}
 public void EndMutation(){mutations=Math.Max(0,mutations-1);Request();}
 public void Dispose(){if(disposed)return;disposed=true;pending.Stop();main.Changed-=Request;shelf.Changed-=Request;foreach(var watcher in watchers.Values)watcher.Dispose();watchers.Clear();}
}
public static class SharedDesktopTests {
 public static async System.Threading.Tasks.Task Run(Box box,Action<string,bool> check){string fixture=Path.Combine(Program.S.Root,"shared-desktop-tests"),root=Path.Combine(fixture,"desktop"),outside=Path.Combine(fixture,"source");Directory.CreateDirectory(root);Directory.CreateDirectory(outside);var main=new Store(Path.Combine(fixture,"main"));var shelf=new Store(Path.Combine(fixture,"shelf"));string first=Path.Combine(root,"原名.txt");File.WriteAllText(first,"contents unchanged");string folder=Path.Combine(root,"资料");Directory.CreateDirectory(folder);string child=Path.Combine(folder,"子文件.txt");File.WriteAllText(child,"child");string alias=Path.Combine(root,"应用.url");File.WriteAllText(alias,"[InternetShortcut]\r\nURL=https://example.invalid\r\n");int paints=0;using(var sync=new DesktopFiles(main,shelf,root,()=>paints++)){sync.Sync();check("桌面实文件同时进入两个面板且应用链接仅在主面板",main.Data.Items.Any(i=>i.Path==first)&&shelf.Data.Items.Any(i=>i.Path==first)&&main.Data.Items.Any(i=>i.Path==alias)&&!shelf.Data.Items.Any(i=>i.Path==alias));var original=main.Data.Items.First(i=>i.Path==first);string group=main.NewGroup("保留分类");original.Group=group;main.Save();string id=original.Id;string renamed=sync.Rename(first,"重命名.txt");check("真实重命名保留文件内容和主面板ID分类并同步两边",!File.Exists(first)&&File.ReadAllText(renamed)=="contents unchanged"&&original.Id==id&&original.Group==group&&shelf.Data.Items.Any(i=>i.Path==renamed&&i.Name=="重命名.txt"));File.WriteAllText(Path.Combine(root,"占用.txt"),"existing");bool collision=false;try{sync.Rename(renamed,"占用.txt");}catch(IOException){collision=true;}check("重命名冲突不覆盖现有文件",collision&&File.ReadAllText(renamed)=="contents unchanged"&&File.ReadAllText(Path.Combine(root,"占用.txt"))=="existing");bool invalid=false;try{sync.Rename(renamed,"CON.txt");}catch(InvalidDataException){invalid=true;}check("重命名拒绝Windows保留名称",invalid&&File.Exists(renamed));foreach(var store in new[]{main,shelf}){store.Data.Items.Add(new Item{Path=child,Name="child"});store.Save();}string newFolder=sync.Rename(folder,"新资料");string newChild=Path.Combine(newFolder,"子文件.txt");check("文件夹改名同步子路径且原内容保留",File.Exists(newChild)&&main.Data.Items.Any(i=>i.Path==newChild)&&shelf.Data.Items.Any(i=>i.Path==newChild));string source=Path.Combine(outside,"移动.txt");File.WriteAllText(source,"move bytes");string moved=DesktopStorage.Import(source,root,null,true);sync.Sync();check("外部拖入移动真实文件到桌面并同步两个入口",!File.Exists(source)&&File.ReadAllText(moved)=="move bytes"&&main.Data.Items.Any(i=>i.Path==moved)&&shelf.Data.Items.Any(i=>i.Path==moved));string nested=Path.Combine(newFolder,"内层.txt");File.WriteAllText(nested,"nested bytes");string top=DesktopStorage.Import(nested,root,null,true);sync.Sync();check("桌面子目录拖入也移到桌面根目录",Path.GetDirectoryName(top)==root&&!File.Exists(nested)&&File.ReadAllText(top)=="nested bytes");string collisionSource=Path.Combine(outside,"占用.txt");File.WriteAllText(collisionSource,"new value");string collisionTarget=DesktopStorage.Import(collisionSource,root,null,true);check("移动同名文件自动编号且原有文件不变",collisionTarget!=Path.Combine(root,"占用.txt")&&!File.Exists(collisionSource)&&File.ReadAllText(Path.Combine(root,"占用.txt"))=="existing");string moveDirectory=Path.Combine(outside,"移动目录");Directory.CreateDirectory(moveDirectory);File.WriteAllText(Path.Combine(moveDirectory,"内容.txt"),"folder content");string movedDirectory=DesktopStorage.Import(moveDirectory,root,null,true);check("移动文件夹保留子文件并移除原目录",!Directory.Exists(moveDirectory)&&File.ReadAllText(Path.Combine(movedDirectory,"内容.txt"))=="folder content");string fresh=Path.Combine(root,"桌面新增.docx");File.WriteAllText(fresh,"watch fixture");await System.Threading.Tasks.Task.Delay(650);check("真实文件监视自动同步桌面新增",main.Data.Items.Any(i=>i.Path==fresh)&&shelf.Data.Items.Any(i=>i.Path==fresh));string freshName=Path.Combine(root,"桌面改名.docx");string externalId=main.Data.Items.First(i=>i.Path==fresh).Id;File.Move(fresh,freshName);await System.Threading.Tasks.Task.Delay(650);check("桌面外部重命名自动同步且保留身份",main.Data.Items.Any(i=>i.Path==freshName&&i.Id==externalId)&&shelf.Data.Items.Any(i=>i.Path==freshName));string outPath=Path.Combine(outside,"移出.docx");File.Move(freshName,outPath);await System.Threading.Tasks.Task.Delay(650);check("外部移出桌面自动移除两边入口且文件仍存在",File.Exists(outPath)&&!main.Data.Items.Any(i=>i.Path==freshName)&&!shelf.Data.Items.Any(i=>i.Path==freshName));sync.Sync();var recycled=RecycleEntry.Send(renamed,IntPtr.Zero);sync.Removed(renamed,false);check("从任一面板删除实际回收文件并同步移除两个入口",File.Exists(recycled.Destination)&&!main.Data.Items.Any(i=>i.Path==renamed)&&!shelf.Data.Items.Any(i=>i.Path==renamed));string crossSource=Path.Combine(Path.GetTempPath(),"rushbin-cross-"+Guid.NewGuid().ToString("N")+".txt");File.WriteAllText(crossSource,"cross-volume fixture");string crossRoot=Path.Combine(Program.OutDir,"cross-volume-fixture",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(crossRoot);string cross=DesktopStorage.Import(crossSource,crossRoot,null,true);check("Shell移动支持跨磁盘且保留内容",!File.Exists(crossSource)&&File.ReadAllText(cross)=="cross-volume fixture");var itemCommands=NativeFileMenu.Show(box,cross,false,null,true);var background=NativeFileMenu.Show(box,root,true,null,true);check("真实Windows文件和背景菜单可取得原生命令",itemCommands.Length>0&&background.Length>0);sync.Sync();check("同步结果保存后重载仍对应同一批实际文件",new Store(main.Root).Data.Items.Any(i=>i.Path==top)&&new Store(shelf.Root).Data.Items.Any(i=>i.Path==top));File.WriteAllText(Path.Combine(Program.OutDir,"微桌面同步核对.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{main=main.Data.Items.Select(i=>new{i.Path,i.Group,i.Id}).ToArray(),files=shelf.Data.Items.Select(i=>i.Path).ToArray(),itemCommands,background,paints,scope="Own isolated desktop and files. Real filesystem watcher, real rename/move and Recycle Bin, native Shell menu query. No physical Explorer drag or user-file operations."}));}}
}
